        String uuidValue = params.has("uuid") ? params.get("uuid").getAsString() : null;
        if (uuidValue == null || uuidValue.trim().isEmpty()) {
            uuidValue = java.util.UUID.randomUUID().toString();
            params.addProperty("uuid", uuidValue);
        }
        return uuidValue;
    }

